INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (364698, 14908, 'Navbharat Times', 'hi', 'India Bangladesh , बांग्लादेश अनाज से लेकर ईंधन तक के लिए भारत पर निर्भर , फिर मोदी सरकार को आंख क्यों दिखा रहे तारिक रहमान ? - tarique rahman india visit why is bangladesh acting defiantly', 'https://navbharattimes.indiatimes.com/world/asian-countries/tarique-rahman-india-visit-why-is-bangladesh-acting-defiantly/articleshow/133302313.cms', '', 'https://static.langimg.com/nbt/thumb/133302378/india-bangladesh-news.jpg?imgsize=139422&resizemode=75', '20260817', '2026-08-17T22:43:09.202398'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365103, 14908, 'Republic World', 'en', 'Cannot Afford To Keep India At Arm''s Length: Why Bangladesh Needs India More Than Ever As Tarique Rahman Eyes August 21-26 Visit', 'https://news.google.?oc=5', 'Cannot Afford To Keep India At Arm''s Length: Why Bangladesh Needs India More Than Ever As Tarique Rahman Eyes August 21-26 Visit republicworld.com', '', '2026-08-17T23:46:59+00:00', '2026-08-18T03:05:53.184481'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365251, 14908, 'Aaj Tak', 'hi', 'बिजली संकट और भूगोल, क्यों भारत पर निर्भर बांग्लादेश? देखें कूटनीति', 'https://www.aajtak.in/world/video/bangladesh-trying-diplomatic-bargaining-with-india-tarique-rahman-asks-for-returning-sheikh-hasina-world-news-vdos-2624386-2026-08-18', 'बांग्लादेश भारत के साथ कूटनीतिक सौदेबाजी करने की कोशिश कर रहा है. तारिक रहमान का कहना है कि वे तब तक नई दिल्ली नहीं आएंगे, जब तक भारत शेख हसीना को उनके हवाले नहीं कर देता. क्या ढाका सच में एक द्विपक्षीय दौरे को प्रत्यर्पण की शर्त से जोड़ रहा है? भारत लगातार संबंधों को बेहतर बनाने की कोशिश कर रहा है, लेकिन ढाका हर कदम पर एक नई शर्त रख देता है. बांग्लादेश शेख हसीना के मुद्दे को भारत की परेशानी बनाना चाहता है, जबकि भारत के विदेश मंत्रालय ने साफ कर दिया है कि हसीना के बयानों से भारत का कोई लेना-देना नहीं है.', '', '2026-08-18T01:29:50+00:00', '2026-08-18T03:06:11.696478'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365269, 14908, 'The Lallantop', 'hi', 'भारत दौरे के लिए तारिक रहमान ने दो शर्तें रखीं, पहली शेख हसीना का प्रत्यर्पण, दूसरी क्या है? | The Lallantop', 'https://news.google.?oc=5', 'भारत दौरे के लिए तारिक रहमान ने दो शर्तें रखीं, पहली शेख हसीना का प्रत्यर्पण, दूसरी क्या है? | The Lallantop The Lallantop', '', '2026-08-16T17:40:18+00:00', '2026-08-18T03:06:21.129207'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
