INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349987, 14937, 'France 24', 'en', 'West Bank: Activist recounts life under settler siege in Qusra', 'https://www.france24.com/en/west-bank-activist-recounts-life-under-settler-siege-in-qusra', 'A week after Israeli settlers began besieging Palestinian homes in the West Bank village of Qusra, human rights activist Netanael Hanadaro joined FRANCE 24 to recount what he witnessed there. He said he and other NGO members reached the isolated homes on foot and left food outside for the trapped residents, with the Israeli army saying it would deliver the supplies. Hanadaro described an extraordinary situation in which the homes, located on the outskirts of the village, have been surrounded by settlers while the army works to prevent clashes between the settlers and activists.', 'https://s.france24.com/media/display/1db63f36-9970-11f1-aa90-005056a90284/w:1024/p:16x9/EN-20260816-140839-141311-CS.jpg', '2026-08-16T14:38:57+00:00', '2026-08-16T22:02:19.580935'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
